SQL = ['\nCREATE TABLE workflow_runs (\n\tproject_id VARCHAR(200) NOT NULL, \n\trun_id VARCHAR(200) NOT NULL, \n\ttask_id VARCHAR(200) NOT NULL, \n\tstate VARCHAR(30) NOT NULL, \n\tepoch INTEGER NOT NULL, \n\towner_id VARCHAR(200), \n\tlease_until TIMESTAMP WITH TIME ZONE, \n\tcancel_requested BOOLEAN NOT NULL, \n\tinput_version VARCHAR(200) NOT NULL, \n\tinput_manifest JSON NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tupdated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\terror_code VARCHAR(100), \n\tPRIMARY KEY (project_id, run_id), \n\tFOREIGN KEY(project_id, task_id) REFERENCES research_tasks (project_id, task_id)\n)\n\n', 'CREATE INDEX ix_workflow_runs_state ON workflow_runs (state)', '\nCREATE TABLE step_receipts (\n\tproject_id VARCHAR(200) NOT NULL, \n\trun_id VARCHAR(200) NOT NULL, \n\tstep_key VARCHAR(200) NOT NULL, \n\toutput JSON NOT NULL, \n\tcommitted_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (project_id, run_id, step_key), \n\tFOREIGN KEY(project_id, run_id) REFERENCES workflow_runs (project_id, run_id)\n)\n\n', '\nCREATE TABLE run_events (\n\tevent_id BIGINT GENERATED BY DEFAULT AS IDENTITY, \n\tproject_id VARCHAR(200) NOT NULL, \n\trun_id VARCHAR(200) NOT NULL, \n\tkind VARCHAR(100) NOT NULL, \n\tdata JSON NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (event_id), \n\tFOREIGN KEY(project_id, run_id) REFERENCES workflow_runs (project_id, run_id)\n)\n\n']

